var t=`0289-vanilice`;var n=`world-0289`;var a=`RS`;var r=`southern-europe`;var s=8;var o=39;var g={en:`Vanilice`,ua:`Ваніліце`};var u={en:`A traditional Serbia dish made with chicken egg, all-purpose flour, walnut. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Сербія. Основні інгредієнти: куряче яйце, пшеничне борошно універсальне, волоський горіх. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var l=[{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:10,i:[[`unsalted-butter`,240,`g`],[`white-granulated-sugar`,110,`g`],[`chicken-egg`,2,`pcs`],[`all-purpose-flour`,420,`g`],[`vanilla-extract`,4,`ml`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Bake in a preheated 180°C oven for about 14 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 14 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:14,i:[[`walnut`,130,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`powdered-sugar`,100,`g`],[`apricot-jam`,110,`g`]]}];var d={slug:t,id:n,country:`RS`,region:r,servings:8,minutes:39,title:g,text:u,steps:l};export{a as country,d as default,n as id,o as minutes,r as region,s as servings,t as slug,l as steps,u as text,g as title};